const CURRENCIES=['PHP','USD','SGD','EUR','GBP','JPY','AUD','CAD','HKD','CNY','KRW','AED','SAR','MYR','THB','IDR','TWD','NZD','CHF'];
const money=(n,c='PHP')=>{try{return new Intl.NumberFormat('en-PH',{style:'currency',currency:c,minimumFractionDigits:2}).format(Number(n||0))}catch{return `${c} ${Number(n||0).toFixed(2)}`}};
const capFirst=v=>{const s=String(v??'');return s?s.charAt(0).toUpperCase()+s.slice(1):s};
const ownerCompareText=v=>String(v??'').trim().replace(/\s+/g,' ').toLocaleLowerCase();
const lineAmount=x=>{const p=Number(x?.price||0),raw=x?.quantity;const q=raw===null||raw===undefined||raw===''?1:Number(raw);return p*(Number.isFinite(q)?q:1)};
const userColor=id=>{if(!id)return '#98a2b3';let h=0;for(const ch of String(id))h=(h*31+ch.charCodeAt(0))%360;return `hsl(${h} 68% 48%)`};
const safeDate=value=>{if(!value)return 'Date not set';const d=new Date(`${value}T12:00:00`);return Number.isNaN(d.getTime())?'Date not set':d.toLocaleDateString('en-PH')};
const localYMD=d=>{const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};
const sundayWeekStart=(value=new Date())=>{const d=value instanceof Date?new Date(value):new Date(`${value}T12:00:00`);d.setDate(d.getDate()-d.getDay());return localYMD(d)};
