const monthStartYMD=value=>{const d=value?new Date(`${value}T12:00:00`):new Date();return localYMD(new Date(d.getFullYear(),d.getMonth(),1,12))};
function SundayDateInput({value,onChange}){
  const[open,setOpen]=useState(false),[month,setMonth]=useState(()=>monthStartYMD(value)),boxRef=useRef(null);
  useEffect(()=>{if(value)setMonth(monthStartYMD(value))},[value]);
  useEffect(()=>{if(!open)return;const close=e=>{if(boxRef.current&&!boxRef.current.contains(e.target))setOpen(false)};document.addEventListener('pointerdown',close);return()=>document.removeEventListener('pointerdown',close)},[open]);
  const selected=value?new Date(`${value}T12:00:00`):null,m=new Date(`${month}T12:00:00`),first=new Date(m.getFullYear(),m.getMonth(),1,12),gridStart=new Date(first);gridStart.setDate(first.getDate()-first.getDay());
  const days=Array.from({length:42},(_,i)=>{const d=new Date(gridStart);d.setDate(gridStart.getDate()+i);return d});
  const choose=d=>{onChange?.({target:{value:localYMD(d)}});setOpen(false)};
  const moveMonth=n=>{const d=new Date(m);d.setMonth(d.getMonth()+n,1);setMonth(localYMD(d))};
  const display=value?new Date(`${value}T12:00:00`).toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'}):'Select date';
  return <div className="responsiveDatePicker" ref={boxRef}>
    <input className="desktopDateInput" type="date" value={value||''} onChange={onChange}/>
    <button type="button" className="mobileDateButton" onClick={()=>setOpen(v=>!v)}><CalendarDays/><span>{display}</span></button>
    {open&&<div className="mobileSundayCalendar">
      <div className="mobileCalendarHead"><button type="button" onClick={()=>moveMonth(-1)} aria-label="Previous month"><ChevronLeft/></button><b>{m.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}</b><button type="button" onClick={()=>moveMonth(1)} aria-label="Next month"><ChevronRight/></button></div>
      <div className="mobileCalendarWeekdays">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=><span key={x}>{x}</span>)}</div>
      <div className="mobileCalendarGrid">{days.map(d=>{const ymd=localYMD(d),sameMonth=d.getMonth()===m.getMonth(),chosen=selected&&localYMD(selected)===ymd,today=ymd===localYMD(new Date());return <button type="button" key={ymd} className={`${sameMonth?'':'outsideMonth'} ${chosen?'selectedDay':''} ${today?'todayDay':''}`} onClick={()=>choose(d)}>{d.getDate()}</button>})}</div>
      <div className="mobileCalendarWeekHint">Weeks run Sunday–Saturday</div>
    </div>}
  </div>
}
const isAdmin=p=>p?.role==='admin'||p?.role==='super_admin';
const isBlankItem=i=>!String(i.name||'').trim()&&!(i.quantity??'')&&!i.unit_id&&!String(i.price??'').trim()&&!String(i.remarks||'').trim();

